import java.util.Scanner;

public class Main {
    static final int MAXN = 100001;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        int n = sc.nextInt();

        double res = 1e9;
        int p1 = 0, p2 = 0;

        if (y <= n) {
            while (gcd(x, y) > 1) {
                long h = gcd(x, y);
                x /= h;
                y /= h;
            }
            System.out.println(x + "/" + y);
            sc.close();
            return;
        }

        for (int i = 1; i <= n; i++) {
            long h = lca(i, y);
            long w = x * (h / y);
            double temp1 = (w - ((w / (h / i)) * (h / i))) / (double) h;
            if (res > temp1) {
                res = temp1;
                p1 = (int) (w / (h / i));
                p2 = i;
            }
            long numerator = w + (h / i) - 1;
            long denominator = h / i;
            long quotient = numerator / denominator;
            double temp2 = Math.abs(w - (quotient * denominator)) / (double) h;
            if (res > temp2) {
                res = temp2;
                p1 = (int) quotient;
                p2 = i;
            }
        }

        long h = gcd(p1, p2);
        p1 /= h;
        p2 /= h;
        System.out.println(p1 + "/" + p2);
        sc.close();
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static long lca(int a, int b) {
        return a * b / gcd(a, b);
    }
}

